/* @lc app=leetcode id=3435 lang=kotlin */ class Solution { fun acyc(pred: IntArray, r0: Int): Boolean = generateSequence(r0) { r -> if (r == 0) null else pred.indices.filter { r shr it and 1 == 1 && pred[it] and r == 0 }.fold(0) { a, i -> a or (1 shl i) }.let { sr -> if (sr == 0) null else r xor sr } }.last() == 0 fun supersequences(words: Array<String>): List<List<Int>> = words.flatMap { it.toList() }.distinct().let { ls -> ls.size.let { L -> IntArray(L).let { pred -> words.filter { it[0] != it[1] }.forEach { w -> ls.indexOf(w[0]).let { a -> ls.indexOf(w[1]).let { b -> pred[b] = pred[b] or (1 shl a) } } }.let { words.filter { it[0] == it[1] }.fold(0) { m, w -> m or (1 shl ls.indexOf(w[0])) }.let { loops -> (1 shl L).let { full -> (0 until full).filter { sm -> (loops and sm) == loops && acyc(pred, (full - 1) xor sm) }.let { valid -> valid.minOf { Integer.bitCount(it) }.let { mn -> valid.filter { Integer.bitCount(it) == mn }.map { sm -> (0 until 26).map { c -> ls.indexOf('a' + c).let { i -> if (i < 0) 0 else if (sm shr i and 1 == 1) 2 else 1 } } } } } } } } } } } }